/*
 * Generated by Speakeasy, now hand-maintained (.genignore): stdio falls back
 * to PIPESHUB_TOKEN and the `pipeshub login` sign-in.
 */

import { SSEServerTransport } from "@modelcontextprotocol/sdk/server/sse.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import express from "express";
import { LocalContext } from "../../cli.js";
import {
  ConsoleLoggerLevel,
  createConsoleLogger,
} from "../../console-logger.js";
import { MCPServerFlags } from "../../flags.js";
import { createMCPServer } from "../../server.js";

import { landingPageExpress } from "../../../landing-page.js";
import { assertTransport, resolveOrigin, resolveToken } from "../../../cli/config.js";
import { storedLogin } from "../../../cli/login.js";
import { createBridge, type BridgeAuth } from "../../../cli/bridge.js";
import { postMcp, newRequestId } from "../../../cli/client.js";
import { chatEnabledFromEnv } from "../../chat-setting.js";
import { SDKOptions } from "../../../lib/config.js";

interface StartCommandFlags extends MCPServerFlags {
  readonly transport: "stdio" | "sse";
  readonly port: number;
  readonly "log-level": ConsoleLoggerLevel;
  readonly env?: [string, string][];
}

interface Session {
  mcpServer: ReturnType<typeof createMCPServer>["server"];
  transport: SSEServerTransport;
  cleanup: () => Promise<void>;
}

export async function main(this: LocalContext, flags: StartCommandFlags) {
  flags.env?.forEach(([key, value]) => {
    process.env[key] = value;
  });

  switch (flags.transport) {
    case "stdio":
      await startStdio(flags);
      break;
    case "sse":
      await startSSE(flags);
      break;
    default:
      throw new Error(`Invalid transport: ${flags.transport}`);
  }
}

/**
 * The stdio credential when the command line names none: PIPESHUB_TOKEN (or
 * PIPESHUB_MCP_TOKEN), then the `pipeshub login` sign-in, read and refreshed
 * on each request. So a client config needs no token in it at all.
 */
async function stdioCredential(
  flags: StartCommandFlags,
  logger: ReturnType<typeof createConsoleLogger>,
): Promise<{ security: SDKOptions["security"]; serverURL: string | undefined; proxy?: BridgeAuth }> {
  const fromFlags = {
    security: {
      bearerAuth: flags["bearer-auth"] ?? "",
      oauth2: flags["client-id"] != null && flags["client-secret"] != null
        ? {
          clientID: flags["client-id"] || "",
          clientSecret: flags["client-secret"] || "",
          tokenURL: flags["token-url"] || "",
        }
        : undefined,
    },
    serverURL: flags["server-url"],
  };
  // An empty --bearer-auth (a client config with the field left blank) counts as none.
  if (flags["bearer-auth"] || fromFlags.security.oauth2) {
    const bearer = flags["bearer-auth"];
    const named = flags["server-url"];
    return bearer && named && !fromFlags.security.oauth2
      ? { ...fromFlags, proxy: { origin: new URL(named).origin, token: async () => bearer } }
      : fromFlags;
  }

  // A token goes only to an address that was named (--server-url, else
  // PIPESHUB_BASE_URL / PIPESHUB_MCP_URL), never to the SDK's default, and only
  // under the CLI's cleartext rule. `start` has no --insecure-http.
  const allowed = (origin: string): boolean => {
    try {
      assertTransport(origin, false);
      return true;
    } catch (e) {
      logger.error((e as Error).message);
      return false;
    }
  };
  let origin: string | null;
  try {
    origin = flags["server-url"] ? new URL(flags["server-url"]).origin : resolveOrigin();
  } catch (e) {
    logger.error((e as Error).message);
    return fromFlags;
  }
  const apiBase = (o: string): string => flags["server-url"] ?? `${o}/api/v1`;
  const envToken = resolveToken();
  if (envToken !== null && origin !== null) {
    return allowed(origin)
      ? { security: { bearerAuth: envToken }, serverURL: apiBase(origin), proxy: { origin, token: async () => envToken } }
      : fromFlags;
  }

  // A sign-in is used only for its own origin; with no address named, it names the instance.
  const signedIn = await storedLogin(origin, false).catch((e: unknown) => {
    logger.error((e as Error).message);
    return null;
  });
  if (signedIn === null) {
    logger.error(
      envToken !== null
        ? "PIPESHUB_TOKEN is set but no PipesHub address is: pass --server-url or set PIPESHUB_BASE_URL."
        : "No PipesHub credential: pass --bearer-auth, set PIPESHUB_TOKEN, or run 'pipeshub login'.",
    );
    return fromFlags;
  }
  if (!allowed(signedIn.origin)) return fromFlags;
  return {
    security: async () => {
      assertTransport(signedIn.origin, false);
      return { bearerAuth: (await storedLogin(signedIn.origin, false))?.accessToken ?? "" };
    },
    serverURL: apiBase(signedIn.origin),
    proxy: {
      origin: signedIn.origin,
      token: async () => {
        assertTransport(signedIn.origin, false);
        return (await storedLogin(signedIn.origin, false))?.accessToken ?? "";
      },
    },
  };
}

/**
 * False only when /mcp is not an MCP endpoint there (404/405, or an answer that is not a JSON-RPC response): an older
 * server. An instance that is down, refuses the sign-in or errors still gets the proxy, which says so on each call.
 */
async function hasMcpEndpoint(auth: BridgeAuth, logger: ReturnType<typeof createConsoleLogger>): Promise<boolean> {
  try {
    await postMcp({ origin: auth.origin, token: await auth.token(), insecureHttp: false, requestId: newRequestId(), timeoutMs: 10_000 }, { method: "tools/list" }, 10_000);
    return true;
  } catch (e) {
    if (/HTTP (404|405)\b|could not parse the MCP response|MCP response contained no result|empty response from the MCP|sent no JSON-RPC response/.test((e as Error).message)) {
      logger.warning(`${auth.origin} has no /mcp endpoint; using the per-tool server instead.`);
      return false;
    }
    return true;
  }
}

async function startStdio(flags: StartCommandFlags) {
  const logger = createConsoleLogger(flags["log-level"]);
  const transport = new StdioServerTransport();
  const { security, serverURL, proxy } = await stdioCredential(flags, logger);
  // Default: a proxy to the instance's own /mcp, so the agent sees the server's full tool set. The generated per-tool
  // server is used when the person asked for its modes (--tool, --scope, --mode dynamic), or the instance has no /mcp.
  if (proxy && !flags.tool?.length && !flags.scope?.length && !flags.mode && (await hasMcpEndpoint(proxy, logger))) {
    const bridge = createBridge({ auth: proxy, chat: chatEnabledFromEnv(), log: (l) => logger.info(l) });
    await bridge.connect(transport);
    const stop = async () => {
      await bridge.close();
      process.exit(0);
    };
    process.on("SIGTERM", stop);
    process.on("SIGINT", stop);
    return;
  }
  const { server } = createMCPServer({
    logger,
    allowedTools: flags.tool,
    dynamic: flags.mode === "dynamic",
    scopes: flags.scope,
    security,
    serverURL,
    serverIdx: flags["server-index"],
    instance_url: flags["instance-url"],
  });
  await server.connect(transport);

  const abort = async () => {
    await server.close();
    process.exit(0);
  };
  process.on("SIGTERM", abort);
  process.on("SIGINT", abort);
}

async function startSSE(cliFlags: StartCommandFlags) {
  const logger = createConsoleLogger(cliFlags["log-level"]);
  const app = express();
  const sessions = new Map<string, Session>();
  const controller = new AbortController();

  app.get("/sse", async (req, res) => {
    const sessionId = crypto.randomUUID();

    logger.info("SSE connection initiated", {
      sessionId,
      userAgent: req.headers["user-agent"],
    });

    // Track early disconnection
    let connectionClosed = false;
    res.on("close", () => {
      if (!connectionClosed) {
        logger.info("Connection closed early", { sessionId });
      }
      connectionClosed = true;
    });

    // Merge CLI flags with header overrides for security credentials
    const flags: StartCommandFlags = {
      ...cliFlags,
      // Security fields can be overridden via headers
      "bearer-auth": (req.headers["bearerauth"] as string)
        ?? cliFlags["bearer-auth"],
      "client-id": (req.headers["clientid"] as string) ?? cliFlags["client-id"],
      "client-secret": (req.headers["clientsecret"] as string)
        ?? cliFlags["client-secret"],
      "token-url": (req.headers["tokenurl"] as string) ?? cliFlags["token-url"],
    };

    // Create a new MCP server for this connection with its auth
    const { server: mcpServer } = createMCPServer({
      logger,
      allowedTools: flags.tool,
      dynamic: flags.mode === "dynamic",
      scopes: flags.scope,
      security: {
        bearerAuth: flags["bearer-auth"] ?? "",
        oauth2: flags["client-id"] != null && flags["client-secret"] != null
          ? {
            clientID: flags["client-id"] || "",
            clientSecret: flags["client-secret"] || "",
            tokenURL: flags["token-url"] || "",
          }
          : undefined,
      },
      serverURL: flags["server-url"],
      serverIdx: flags["server-index"],
      instance_url: flags["instance-url"],
    });

    // Message path includes session ID for routing
    const transport = new SSEServerTransport(`/message/${sessionId}`, res);

    const cleanup = async () => {
      await mcpServer.close();
    };

    sessions.set(sessionId, { mcpServer, transport, cleanup });
    logger.info("Session created", { sessionId, totalSessions: sessions.size });
    controller.signal.addEventListener("abort", cleanup);

    // Log server-side errors for debugging (e.g. tools/list handler failures)
    mcpServer.server.onerror = (error) => {
      logger.error("MCP protocol error", {
        sessionId,
        error: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined,
      });
    };

    // Wrap transport.send to log error responses for debugging
    const originalSend = transport.send.bind(transport);
    transport.send = async (message) => {
      if ("error" in message && message.error) {
        logger.error("MCP sending error response", {
          sessionId,
          id: message.id,
          errorCode: message.error.code,
          errorMessage: message.error.message,
        });
      }
      return originalSend(message);
    };

    await mcpServer.connect(transport);

    mcpServer.server.onclose = async () => {
      connectionClosed = true;
      controller.signal.removeEventListener("abort", cleanup);
      sessions.delete(sessionId);
      logger.info("Session closed", {
        sessionId,
        totalSessions: sessions.size,
      });
      res.end();
    };
  });

  app.post("/message/:sessionId", async (req, res) => {
    const session = sessions.get(req.params.sessionId);
    if (!session) {
      res.status(404).send("Session not found");
      return;
    }

    await session.transport.handlePostMessage(req, res);
  });

  app.get("/", landingPageExpress);

  const httpServer = app.listen(cliFlags.port, "0.0.0.0", () => {
    const ha = httpServer.address();
    const host = typeof ha === "string" ? ha : `${ha?.address}:${ha?.port}`;
    logger.info("MCP HTTP server started", { host });
  });

  let closing = false;
  controller.signal.addEventListener("abort", async () => {
    if (closing) {
      logger.info("Received second signal. Forcing shutdown.");
      process.exit(1);
    }
    closing = true;

    logger.info("Shutting down HTTP server");

    const timer = setTimeout(() => {
      logger.info("Forcing shutdown");
      process.exit(1);
    }, 5000);

    httpServer.close(() => {
      clearTimeout(timer);
      logger.info("Graceful shutdown complete");
      process.exit(0);
    });
  });

  const abort = () => controller.abort();
  process.on("SIGTERM", abort);
  process.on("SIGINT", abort);
}
